select case when p.stock_qty >= 444 then 'high' when p.stock_qty >= 123 then 'mid' else 'low' end as stock_qty_bucket, p.brand, round(stddev(ss.units), 2) as stddev_units, max(ss.revenue) - min(ss.revenue) as revenue_range from store_sales ss inner join products p on ss.product_id = p.id group by case when p.stock_qty >= 444 then 'high' when p.stock_qty >= 123 then 'mid' else 'low' end, p.brand having max(ss.revenue) - min(ss.revenue) > 55 order by brand;
